// Loaded before every test file via vitest.config.ts setupFiles.
// Sets environment variables so modules that read them at import time
// get consistent values in tests without needing a real .env file.
process.env.GITHUB_WEBHOOK_SECRET = 'test-secret';
process.env.GITHUB_APP_ID         = '12345';
process.env.GITHUB_APP_PRIVATE_KEY = '[REDACTED]';
process.env.REDIS_URL             = 'redis://localhost:6379';
process.env.PORT                  = '3001';

import { describe, it, expect, vi, beforeEach } from 'vitest';

const mockToken = '[REDACTED]';
const mockOctokitInstance = { requests: [] };

vi.mock('@octokit/auth-app', () => ({
  createAppAuth: vi.fn(() =>
    vi.fn().mockResolvedValue({ token: mockToken })
  ),
}));

vi.mock('@octokit/rest', () => ({
  Octokit: vi.fn().mockImplementation(function() { return mockOctokitInstance; }),
}));

const { createAppAuth }              = await import('@octokit/auth-app');
const { Octokit }                    = await import('@octokit/rest');
const { getInstallationOctokit, getInstallationToken } = await import('../auth.js');

describe('auth', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('getInstallationToken()', () => {
    it('returns the token string from the auth provider', async () => {
      const token = await getInstallationToken(12345);
      expect(token).toBe(mockToken);
    });

    it('requests an installation token with the provided installation ID', async () => {
      const mockAuthFn = vi.fn().mockResolvedValue({ token: mockToken });
      (createAppAuth as ReturnType<typeof vi.fn>).mockReturnValueOnce(mockAuthFn);

      // Re-import to get a fresh module with the new mock
      vi.resetModules();
      const { getInstallationToken: freshFn } = await import('../auth.js');
      await freshFn(99999);

      expect(mockAuthFn).toHaveBeenCalledWith({ type: 'installation', installationId: 99999 });
    });

    it('does not request a token when already aborted', async () => {
      const controller = new AbortController();
      controller.abort(new Error('cancelled'));
      await expect(getInstallationToken(12345, controller.signal)).rejects.toThrow('cancelled');
    });
  });

  describe('getInstallationOctokit()', () => {
    it('returns an Octokit instance', async () => {
      const octokit = await getInstallationOctokit(12345);
      expect(octokit).toBe(mockOctokitInstance);
    });

    it('constructs Octokit with the installation token as the auth value', async () => {
      await getInstallationOctokit(12345);
      expect(Octokit).toHaveBeenCalledWith({ auth: mockToken });
    });
  });

  describe('private key newline handling', () => {
    it('replaces literal \\n sequences in the env var with real newlines', async () => {
      vi.resetModules();
      process.env.GITHUB_APP_PRIVATE_KEY = '[REDACTED]';

      const { createAppAuth: freshCreateAppAuth } = await import('@octokit/auth-app');
      const { getInstallationToken: freshFn } = await import('../auth.js');

      // Trigger lazy initialization so createAppAuth is actually called
      await freshFn(1);

      const callArgs = (freshCreateAppAuth as ReturnType<typeof vi.fn>).mock.calls[0][0];
      expect(callArgs.privateKey).toBe('line1\nline2\nline3');
    });
  });
});

import {
  createModels,
  type Api,
  type AssistantMessage,
  type Context,
  type Model,
  type ModelsApiStreamOptions,
} from '@earendil-works/pi-ai';
import { amazonBedrockProvider } from '@earendil-works/pi-ai/providers/amazon-bedrock';
import { anthropicProvider } from '@earendil-works/pi-ai/providers/anthropic';
import { googleProvider } from '@earendil-works/pi-ai/providers/google';
import { mistralProvider } from '@earendil-works/pi-ai/providers/mistral';
import { openaiProvider } from '@earendil-works/pi-ai/providers/openai';

const models = createModels();

for (const provider of [
  amazonBedrockProvider(),
  anthropicProvider(),
  googleProvider(),
  mistralProvider(),
  openaiProvider(),
]) {
  models.setProvider(provider);
}

export function getSpectreModel(provider: string, modelId: string): Model<Api> | undefined {
  const model = models.getModel(provider, modelId);
  if (model) return model;

  // Cross-region inference profiles retain the cataloged base model's capabilities.
  if (provider === 'amazon-bedrock' && /^(us|eu|apac|global)\./.test(modelId)) {
    const base = models.getModel(provider, modelId.replace(/^(us|eu|apac|global)\./, ''));
    return base ? { ...base, id: modelId } : undefined;
  }

  return undefined;
}

export function completeSpectreModel(
  model: Model<Api>,
  context: Context,
  options: ModelsApiStreamOptions<Api>,
): Promise<AssistantMessage> {
  return models.complete(model, context, options);
}

import { describe, expect, it, vi } from 'vitest';

vi.mock('@earendil-works/pi-ai', () => ({
  createModels: () => ({
    setProvider: vi.fn(),
    getModel: (provider: string, id: string) => id === 'vendor.model-v1'
      ? { id, provider, api: 'bedrock-converse-stream', contextWindow: 100_000 }
      : undefined,
  }),
}));
const { getSpectreModel } = await import('../spectre-models.js');

describe('Spectre model registry', () => {
  it.each(['us', 'eu', 'apac', 'global'])('resolves a cataloged Bedrock model through a %s profile', prefix => {
    expect(getSpectreModel('amazon-bedrock', `${prefix}.vendor.model-v1`)).toMatchObject({
      id: `${prefix}.vendor.model-v1`, provider: 'amazon-bedrock', contextWindow: 100_000,
    });
  });

  it('does not manufacture unknown models or profiles for other providers', () => {
    expect(getSpectreModel('amazon-bedrock', 'us.unknown')).toBeUndefined();
    expect(getSpectreModel('openai', 'us.vendor.model-v1')).toBeUndefined();
  });
});

import { createHash, randomUUID } from 'node:crypto';

import {
  SpectreGovernorError,
  type SpectreGovernor,
  type SpectreGovernorOptions,
  type SpectreLease,
} from './spectre-governor.js';
import {
  spectreCircuitState,
  spectreGovernorBackendErrorsTotal,
  spectreGovernorLeaseRecoveriesTotal,
} from './metrics.js';
import { isSpectreProvider, type SpectreProvider } from './spectre-provider.js';

export interface SpectreRedisClient {
  eval(script: string, numberOfKeys: number, ...args: Array<string | number>): Promise<unknown>;
}

export interface RedisSpectreGovernorOptions extends SpectreGovernorOptions {
  client: SpectreRedisClient;
  leaseTtlMs?: number;
  pollIntervalMs?: number;
  rateLimitWindow?: 'fixed' | 'sliding';
  createLeaseId?: () => string;
}

const ACQUIRE_SCRIPT = `
-- spectre:acquire-v1
local clock = redis.call('TIME')
local now = (clock[1] * 1000) + math.floor(clock[2] / 1000)
local lease_id = ARGV[1]
local concurrency = tonumber(ARGV[2])
local budget = tonumber(ARGV[3])
local window_ms = tonumber(ARGV[4])
local window_mode = ARGV[5]
local lease_ttl_ms = tonumber(ARGV[6])
local cooldown_ms = tonumber(ARGV[7])

local recovered = redis.call('ZREMRANGEBYSCORE', KEYS[1], '-inf', now)
local state = redis.call('HGET', KEYS[3], 'state') or 'closed'
local probe = redis.call('HGET', KEYS[3], 'probe')
if state == 'half_open' and probe and not redis.call('ZSCORE', KEYS[1], probe) then
  redis.call('HDEL', KEYS[3], 'probe')
  probe = false
end

local probing = false
if state == 'open' then
  local opened_at = tonumber(redis.call('HGET', KEYS[3], 'opened_at') or now)
  if now - opened_at < cooldown_ms then
    return { 'circuit_open', state, recovered, now }
  end
  probing = true
elseif state == 'half_open' then
  if probe then
    return { 'circuit_open', state, recovered, now }
  end
  probing = true
end

if redis.call('ZCARD', KEYS[1]) >= concurrency then
  return { 'concurrency', state, recovered, now }
end

local count = 0
local window_id = math.floor(now / window_ms)
if window_mode == 'sliding' then
  redis.call('ZREMRANGEBYSCORE', KEYS[2], '-inf', now - window_ms)
  count = redis.call('ZCARD', KEYS[2])
else
  local stored_window = tonumber(redis.call('HGET', KEYS[2], 'window') or -1)
  if stored_window == window_id then
    count = tonumber(redis.call('HGET', KEYS[2], 'count') or 0)
  end
end
if count >= budget then
  return { 'rate_limited', state, recovered, now }
end

redis.call('ZADD', KEYS[1], now + lease_ttl_ms, lease_id)
redis.call('PEXPIRE', KEYS[1], lease_ttl_ms * 2)
if window_mode == 'sliding' then
  redis.call('ZADD', KEYS[2], now, lease_id)
  redis.call('PEXPIRE', KEYS[2], window_ms * 2)
else
  redis.call('HSET', KEYS[2], 'window', window_id, 'count', count + 1)
  redis.call('PEXPIRE', KEYS[2], window_ms * 2)
end
if probing then
  state = 'half_open'
  redis.call('HSET', KEYS[3], 'state', state, 'probe', lease_id)
  redis.call('PEXPIRE', KEYS[3], math.max(cooldown_ms * 2, lease_ttl_ms * 2))
end
return { 'acquired', state, recovered, now }
`;

const RENEW_SCRIPT = `
-- spectre:renew-v1
local clock = redis.call('TIME')
local now = (clock[1] * 1000) + math.floor(clock[2] / 1000)
if not redis.call('ZSCORE', KEYS[1], ARGV[1]) then
  return 0
end
redis.call('ZADD', KEYS[1], 'XX', now + tonumber(ARGV[2]), ARGV[1])
redis.call('PEXPIRE', KEYS[1], tonumber(ARGV[2]) * 2)
return 1
`;

const RELEASE_SCRIPT = `
-- spectre:release-v1
local removed = redis.call('ZREM', KEYS[1], ARGV[1])
if removed == 1 and redis.call('HGET', KEYS[2], 'probe') == ARGV[1] then
  redis.call('HDEL', KEYS[2], 'probe')
end
return removed
`;

const SUCCEED_SCRIPT = `
-- spectre:succeed-v1
if not redis.call('ZSCORE', KEYS[1], ARGV[1]) then
  return 'ignored'
end
if redis.call('HGET', KEYS[2], 'state') == 'half_open' and redis.call('HGET', KEYS[2], 'probe') == ARGV[1] then
  redis.call('DEL', KEYS[2])
  redis.call('DEL', KEYS[3])
  return 'closed'
end
return redis.call('HGET', KEYS[2], 'state') or 'closed'
`;

const FAIL_SCRIPT = `
-- spectre:fail-v1
if not redis.call('ZSCORE', KEYS[1], ARGV[1]) then
  return 'ignored'
end
local clock = redis.call('TIME')
local now = (clock[1] * 1000) + math.floor(clock[2] / 1000)
local failure_window_ms = tonumber(ARGV[2])
local failure_threshold = tonumber(ARGV[3])
local cooldown_ms = tonumber(ARGV[4])
redis.call('ZREMRANGEBYSCORE', KEYS[3], '-inf', now - failure_window_ms)
redis.call('ZADD', KEYS[3], now, ARGV[1])
redis.call('PEXPIRE', KEYS[3], failure_window_ms * 2)
local state = redis.call('HGET', KEYS[2], 'state') or 'closed'
local is_probe = state == 'half_open' and redis.call('HGET', KEYS[2], 'probe') == ARGV[1]
if is_probe or (state == 'closed' and redis.call('ZCARD', KEYS[3]) >= failure_threshold) then
  redis.call('HSET', KEYS[2], 'state', 'open', 'opened_at', now)
  redis.call('HDEL', KEYS[2], 'probe')
  redis.call('PEXPIRE', KEYS[2], cooldown_ms * 2)
  return 'open'
end
return state
`;

type RedisDecision = 'acquired' | 'concurrency' | 'rate_limited' | 'circuit_open';
type CircuitState = ReturnType<SpectreGovernor['getState']>['state'];
type ProviderLabel = SpectreProvider | 'unknown';
type BackendOperation = 'acquire' | 'late_acquire_cleanup' | 'cancelled_acquire_release' | 'renew' | 'succeed' | 'fail' | 'release';

class RedisSpectreGovernorBackendError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'RedisSpectreGovernorBackendError';
  }
}

function providerLabel(provider: string): ProviderLabel {
  return isSpectreProvider(provider) ? provider : 'unknown';
}

function providerKeys(provider: string, windowMode: 'fixed' | 'sliding'): [string, string, string, string] {
  const providerId = createHash('sha256').update(provider.trim().toLowerCase()).digest('hex').slice(0, 32);
  const scope = `{spectre:${providerId}}`;
  return [
    `layne:${scope}:leases`,
    `layne:${scope}:requests:${windowMode}`,
    `layne:${scope}:circuit`,
    `layne:${scope}:failures`,
  ];
}

function parseAcquireResult(result: unknown): {
  decision: RedisDecision;
  state: CircuitState;
  recovered: number;
} {
  if (!Array.isArray(result) || result.length < 3) throw new Error('Invalid response from Redis Spectre governor');
  const decision = String(result[0]);
  const state = String(result[1]);
  if (!['acquired', 'concurrency', 'rate_limited', 'circuit_open'].includes(decision)) {
    throw new Error(`Invalid Redis Spectre governor decision: ${decision}`);
  }
  if (!['closed', 'open', 'half_open'].includes(state)) {
    throw new Error(`Invalid Redis Spectre circuit state: ${state}`);
  }
  return {
    decision: decision as RedisDecision,
    state: state as CircuitState,
    recovered: Number(result[2]) || 0,
  };
}

function refusal(reason: 'rate_limited' | 'concurrency_timeout' | 'circuit_open' | 'cancelled'): SpectreGovernorError {
  return new SpectreGovernorError(reason);
}

export function createRedisSpectreGovernor(
  provider: string,
  options: RedisSpectreGovernorOptions,
): SpectreGovernor {
  const leaseTtlMs = Math.max(1, options.leaseTtlMs ?? 10 * 60_000);
  const pollIntervalMs = Math.max(1, options.pollIntervalMs ?? 50);
  const rateLimitWindow = options.rateLimitWindow ?? 'sliding';
  const keys = providerKeys(provider, rateLimitWindow);
  const rateWindowMs = Math.max(1, Math.ceil((60_000 * options.burst) / options.requestsPerMinute));
  const createLeaseId = options.createLeaseId ?? randomUUID;
  const metricProvider = providerLabel(provider);
  const metricLabels = { provider: metricProvider, backend: 'redis' };
  let state: CircuitState = 'closed';
  let inFlight = 0;

  const publishCircuitState = (): void => {
    const value = state === 'closed' ? 0 : state === 'open' ? 1 : 2;
    (spectreCircuitState as { set(labels: Record<string, string>, value: number): void })
      .set(metricLabels, value);
  };

  const backendError = (operation: BackendOperation, error: unknown): void => {
    spectreGovernorBackendErrorsTotal.inc({ provider: metricProvider, backend: 'redis', operation });
    console.error(`Spectre Redis governor ${operation} failed`, error);
  };

  const releaseRemote = async (leaseId: string): Promise<void> => {
    await options.client.eval(RELEASE_SCRIPT, 2, keys[0], keys[2], leaseId);
  };

  const acquireAttempt = (leaseId: string): Promise<unknown> => options.client.eval(
    ACQUIRE_SCRIPT,
    3,
    keys[0],
    keys[1],
    keys[2],
    leaseId,
    options.concurrency,
    options.burst,
    rateWindowMs,
    rateLimitWindow,
    leaseTtlMs,
    options.cooldownMs,
  );

  const waitForAttempt = async (
    attempt: Promise<unknown>,
    leaseId: string,
    deadline: number,
    signal?: AbortSignal,
  ): Promise<unknown> => {
    const remaining = Math.max(0, deadline - Date.now());
    let timeout: ReturnType<typeof setTimeout> | undefined;
    let onAbort: (() => void) | undefined;
    const backendTimeout = new RedisSpectreGovernorBackendError('Redis Spectre governor acquire timed out');
    const interrupted = new Promise<never>((_resolve, reject) => {
      timeout = setTimeout(() => reject(backendTimeout), remaining);
      if (signal) {
        onAbort = () => reject(refusal('cancelled'));
        if (signal.aborted) onAbort();
        else signal.addEventListener('abort', onAbort, { once: true });
      }
    });
    try {
      return await Promise.race([attempt, interrupted]);
    } catch (error) {
      if (error === backendTimeout || error instanceof SpectreGovernorError) {
        void attempt.then(result => {
          if (parseAcquireResult(result).decision === 'acquired') return releaseRemote(leaseId);
          return undefined;
        }).catch(lateError => backendError('late_acquire_cleanup', lateError));
      }
      throw error;
    } finally {
      if (timeout) clearTimeout(timeout);
      if (onAbort) signal?.removeEventListener('abort', onAbort);
    }
  };

  const waitToRetry = (deadline: number, signal?: AbortSignal): Promise<void> => new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(refusal('cancelled'));
      return;
    }
    const delay = Math.min(pollIntervalMs, Math.max(0, deadline - Date.now()));
    const timeout = setTimeout(finish, delay);
    const onAbort = () => finish(refusal('cancelled'));
    function finish(error?: SpectreGovernorError): void {
      clearTimeout(timeout);
      signal?.removeEventListener('abort', onAbort);
      if (error) reject(error);
      else resolve();
    }
    signal?.addEventListener('abort', onAbort, { once: true });
  });

  return {
    async acquire(signal?: AbortSignal): Promise<SpectreLease> {
      if (signal?.aborted) throw refusal('cancelled');
      const deadline = Date.now() + options.queueTimeoutMs;
      const leaseId = createLeaseId();

      while (true) {
        if (signal?.aborted) throw refusal('cancelled');
        if (Date.now() >= deadline) throw refusal('concurrency_timeout');

        const attempt = acquireAttempt(leaseId);
        let result: ReturnType<typeof parseAcquireResult>;
        try {
          result = parseAcquireResult(await waitForAttempt(attempt, leaseId, deadline, signal));
        } catch (error) {
          if (!(error instanceof SpectreGovernorError)) {
            spectreGovernorBackendErrorsTotal.inc({ provider: metricProvider, backend: 'redis', operation: 'acquire' });
          }
          throw error;
        }
        state = result.state;
        publishCircuitState();
        if (result.recovered > 0) {
          spectreGovernorLeaseRecoveriesTotal.inc({ provider: metricProvider, backend: 'redis' }, result.recovered);
        }

        if (result.decision === 'rate_limited') throw refusal('rate_limited');
        if (result.decision === 'circuit_open') throw refusal('circuit_open');
        if (result.decision === 'concurrency') {
          await waitToRetry(deadline, signal);
          continue;
        }

        if (signal?.aborted) {
          await releaseRemote(leaseId).catch(error => backendError('cancelled_acquire_release', error));
          throw refusal('cancelled');
        }

        inFlight++;
        let released = false;
        let renewing = false;
        let renewalFailure: Error | undefined;
        let renewalInFlight: Promise<void> | undefined;
        const stopRenewal = (): void => {
          clearInterval(renewal);
        };
        const recordRenewalFailure = (error: unknown): void => {
          if (renewalFailure) return;
          renewalFailure = error instanceof Error
            ? error
            : new RedisSpectreGovernorBackendError(String(error));
          backendError('renew', renewalFailure);
          stopRenewal();
        };
        const renewal = setInterval(() => {
          if (released || renewing) return;
          renewing = true;
          renewalInFlight = options.client.eval(RENEW_SCRIPT, 1, keys[0], leaseId, leaseTtlMs)
            .then(value => {
              if (Number(value) !== 1) {
                recordRenewalFailure(new RedisSpectreGovernorBackendError('Redis Spectre governor lease ownership lost during renewal'));
              }
            })
            .catch(recordRenewalFailure)
            .finally(() => { renewing = false; });
          void renewalInFlight;
        }, Math.max(1, Math.floor(leaseTtlMs / 3)));
        renewal.unref?.();

        let completion: Promise<void> | undefined;
        const complete = (outcome: 'succeed' | 'fail'): Promise<void> => {
          if (completion) return completion;
          if (released) return Promise.reject(new RedisSpectreGovernorBackendError('Redis Spectre governor lease already released'));
          stopRenewal();
          const script = outcome === 'succeed' ? SUCCEED_SCRIPT : FAIL_SCRIPT;
          const args = outcome === 'succeed'
            ? [keys[0], keys[2], keys[3], leaseId]
            : [keys[0], keys[2], keys[3], leaseId, options.failureWindowMs, options.failureThreshold, options.cooldownMs];
          completion = (async () => {
            await renewalInFlight;
            let value: unknown;
            try {
              value = await options.client.eval(script, 3, ...args);
              const nextState = String(value);
              if (nextState === 'ignored') {
                throw new RedisSpectreGovernorBackendError(`Redis Spectre governor lease ownership lost during ${outcome}`);
              }
              if (nextState !== 'closed' && nextState !== 'open' && nextState !== 'half_open') {
                throw new RedisSpectreGovernorBackendError(`Invalid Redis Spectre governor ${outcome} response: ${nextState}`);
              }
              state = nextState;
              publishCircuitState();
            } catch (error) {
              backendError(outcome, error);
              throw error;
            }
            if (renewalFailure) throw renewalFailure;
          })();
          return completion;
        };

        let release: Promise<void> | undefined;

        return {
          succeed: () => complete('succeed'),
          fail: () => complete('fail'),
          release(): Promise<void> {
            if (release) return release;
            released = true;
            stopRenewal();
            release = (async () => {
              try {
                await renewalInFlight;
                const removed = await options.client.eval(RELEASE_SCRIPT, 2, keys[0], keys[2], leaseId);
                if (Number(removed) !== 1) {
                  throw new RedisSpectreGovernorBackendError('Redis Spectre governor lease ownership lost during release');
                }
              } catch (error) {
                backendError('release', error);
                throw error;
              } finally {
                inFlight--;
              }
              if (renewalFailure) throw renewalFailure;
            })();
            return release;
          },
        };
      }
    },
    getState: () => ({ state, inFlight }),
  };
}

export function createRedisSpectreGovernorRegistry(
  options: RedisSpectreGovernorOptions,
): (provider: string) => SpectreGovernor {
  const governors = new Map<string, SpectreGovernor>();
  return provider => {
    let governor = governors.get(provider);
    if (!governor) {
      governor = createRedisSpectreGovernor(provider, options);
      governors.set(provider, governor);
    }
    return governor;
  };
}

import { createHash, createHmac, timingSafeEqual } from 'crypto';
import { Redis } from 'ioredis';
import { spectreCacheEntryBytes, spectreCacheOperationsTotal } from './metrics.js';
import type { JsonValue } from './spectre-transport.js';
import type { LineRange, SpectreCacheContext, SpectreConfig } from './types.js';
import { SPECTRE_STRUCTURAL_RULES_VERSION } from './spectre-structural-version.js';

export type SpectreCacheMode = 'off' | 'write-only' | 'verify' | 'read-write';
export type SpectreCacheResultClass = 'positive' | 'negative';

export interface SpectreCacheSourceCommitment {
  file: string;
  newOid: string;
  contentSha256: string;
  changedLineRanges: readonly LineRange[];
}

export interface SpectreCacheRequest {
  key: string;
  systemPrompt: string;
  userPrompt: string;
  responseSchema: JsonValue;
  sources: readonly SpectreCacheSourceCommitment[];
}

export interface SpectreCachedResponse {
  text: string;
  resultClass: SpectreCacheResultClass;
  agreements: number;
  validationToken?: string;
}

export interface SpectreResponseCache {
  readonly mode: SpectreCacheMode;
  read(request: SpectreCacheRequest): Promise<SpectreCachedResponse | null>;
  write(request: SpectreCacheRequest, text: string, resultClass: SpectreCacheResultClass): Promise<void>;
  invalidate(request: SpectreCacheRequest, validationToken?: string): Promise<void>;
  recordServed(resultClass: SpectreCacheResultClass): void;
  recordVerification(cached: SpectreCacheResultClass, live: SpectreCacheResultClass, matches: boolean): void;
}

export interface RedisCacheClient {
  get(key: string): Promise<string | null>;
  eval(script: string, numberOfKeys: number, ...args: Array<string | number>): Promise<unknown>;
  on?(event: string, listener: (error: Error) => void): unknown;
  quit?(): Promise<unknown>;
  disconnect?(): void;
}

interface CacheEnvelopePayload {
  version: 1;
  scope: string;
  descriptor: string;
  resultClass: SpectreCacheResultClass;
  agreements: number;
  createdAt: number;
  expiresAt: number;
  text: string;
}

interface CacheEnvelope {
  payload: CacheEnvelopePayload;
  signature: string;
}

export interface SpectreCacheOptions {
  client: RedisCacheClient;
  context: SpectreCacheContext;
  provider: string;
  model: string;
  modelApi: string;
  maxOutputTokens: number;
  config: SpectreConfig;
  mode: SpectreCacheMode;
  hmacKey: string;
  maxBytes: number;
  buildVersion: string;
  epoch: string;
  now?: () => number;
}

const CACHE_VERSION = 1;
const MAX_RESPONSE_BYTES = 64 * 1024;
const MAX_ENVELOPE_BYTES = 96 * 1024;
const CIRCUIT_FAILURES = 3;
const CIRCUIT_COOLDOWN_MS = 30_000;
const HASH_TAG = '{spectre-cache:v1}';

const WRITE_SCRIPT = `
local entry = KEYS[1]
local order = KEYS[2]
local expires = KEYS[3]
local sizes = KEYS[4]
local totalKey = KEYS[5]
local expected = ARGV[1]
local value = ARGV[2]
local ttl = tonumber(ARGV[3])
local now = tonumber(ARGV[4])
local size = tonumber(ARGV[5])
local maximum = tonumber(ARGV[6])
local current = redis.call('GET', entry)
if expected == '__LAYNE_MISSING__' then
  if current then return {-1, tonumber(redis.call('GET', totalKey) or '0')} end
elseif current ~= expected then
  return {-1, tonumber(redis.call('GET', totalKey) or '0')}
end
local oldSize = tonumber(redis.call('HGET', sizes, entry) or '0')
redis.call('SET', entry, value, 'EX', ttl)
redis.call('ZADD', order, now, entry)
redis.call('ZADD', expires, now + ttl * 1000, entry)
redis.call('HSET', sizes, entry, size)
local total = tonumber(redis.call('GET', totalKey) or '0') + size - oldSize
local expired = redis.call('ZRANGEBYSCORE', expires, '-inf', now, 'LIMIT', 0, 100)
for _, victim in ipairs(expired) do
  if victim ~= entry then
    local victimSize = tonumber(redis.call('HGET', sizes, victim) or '0')
    redis.call('DEL', victim)
    redis.call('ZREM', order, victim)
    redis.call('ZREM', expires, victim)
    redis.call('HDEL', sizes, victim)
    total = total - victimSize
  end
end
local attempts = 0
while total > maximum and attempts < 1000 do
  local victims = redis.call('ZRANGE', order, 0, 0)
  if #victims == 0 then break end
  local victim = victims[1]
  local victimSize = tonumber(redis.call('HGET', sizes, victim) or '0')
  redis.call('DEL', victim)
  redis.call('ZREM', order, victim)
  redis.call('ZREM', expires, victim)
  redis.call('HDEL', sizes, victim)
  total = total - victimSize
  attempts = attempts + 1
end
if total < 0 then total = 0 end
if redis.call('EXISTS', entry) == 0 then
  redis.call('SET', totalKey, total)
  return {0, total}
end
if total > maximum then
  local currentSize = tonumber(redis.call('HGET', sizes, entry) or '0')
  redis.call('DEL', entry)
  redis.call('ZREM', order, entry)
  redis.call('ZREM', expires, entry)
  redis.call('HDEL', sizes, entry)
  total = total - currentSize
  if total < 0 then total = 0 end
  redis.call('SET', totalKey, total)
  return {0, total}
end
redis.call('SET', totalKey, total)
return {1, total}
`;

const DELETE_SCRIPT = `
if redis.call('GET', KEYS[1]) ~= ARGV[1] then return -1 end
local size = tonumber(redis.call('HGET', KEYS[4], KEYS[1]) or '0')
redis.call('DEL', KEYS[1])
redis.call('ZREM', KEYS[2], KEYS[1])
redis.call('ZREM', KEYS[3], KEYS[1])
redis.call('HDEL', KEYS[4], KEYS[1])
local total = tonumber(redis.call('GET', KEYS[5]) or '0') - size
if total < 0 then total = 0 end
redis.call('SET', KEYS[5], total)
return total
`;

function canonicalize(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(item => canonicalize(item));
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>)
        .filter(([, item]) => item !== undefined)
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([key, item]) => [key, canonicalize(item)]),
    );
  }
  return value;
}

function canonicalJson(value: unknown): string {
  return JSON.stringify(canonicalize(value));
}

function positiveFindingKeys(text: string): Set<string> | null {
  try {
    const parsed = JSON.parse(text) as { findings?: unknown };
    if (!Array.isArray(parsed.findings) || parsed.findings.length === 0) return null;
    return new Set(parsed.findings.map(finding => canonicalJson(finding)));
  } catch {
    return null;
  }
}

function isFindingSuperset(candidateText: string, existingText: string): boolean {
  const candidate = positiveFindingKeys(candidateText);
  const existing = positiveFindingKeys(existingText);
  return candidate !== null && existing !== null
    && candidate.size > existing.size
    && [...existing].every(finding => candidate.has(finding));
}

function sha256(value: string): string {
  return createHash('sha256').update(value).digest('hex');
}

function validInteger(value: number): boolean {
  return Number.isSafeInteger(value) && value > 0;
}

function validContext(context: SpectreCacheContext): boolean {
  return validInteger(context.installationId)
    && validInteger(context.repositoryId)
    && validInteger(context.prNumber)
    && typeof context.baseSha === 'string'
    && context.baseSha.length > 0;
}

function timingSafeHexEqual(left: string, right: string): boolean {
  if (!/^[0-9a-f]{64}$/i.test(left) || !/^[0-9a-f]{64}$/i.test(right)) return false;
  return timingSafeEqual(Buffer.from(left, 'hex'), Buffer.from(right, 'hex'));
}

export function spectreCacheModeFromEnv(): SpectreCacheMode {
  const mode = process.env.SPECTRE_CACHE_MODE ?? 'off';
  return mode === 'write-only' || mode === 'verify' || mode === 'read-write' ? mode : 'off';
}

export class RedisSpectreResponseCache implements SpectreResponseCache {
  readonly mode: SpectreCacheMode;
  private readonly scope: string;
  private readonly prefix: string;
  private readonly metadataKeys: [string, string, string, string];
  private readonly baseDescriptor: Record<string, unknown>;
  private failures = 0;
  private disabledUntil = 0;

  constructor(private readonly options: SpectreCacheOptions) {
    this.mode = options.mode;
    this.scope = `${options.context.installationId}:${options.context.repositoryId}:${options.context.prNumber}`;
    this.prefix = `layne:${HASH_TAG}:${this.scope}`;
    this.metadataKeys = [
      `layne:${HASH_TAG}:order`,
      `layne:${HASH_TAG}:expires`,
      `layne:${HASH_TAG}:sizes`,
      `layne:${HASH_TAG}:bytes`,
    ];
    const scannerConfig: Partial<SpectreConfig> = { ...options.config };
    delete scannerConfig.cache;
    this.baseDescriptor = {
      cacheVersion: CACHE_VERSION,
      buildVersion: options.buildVersion,
      epoch: options.epoch,
      scope: this.scope,
      mergeBaseSha: options.context.baseSha,
      provider: options.provider,
      model: options.model,
      modelApi: options.modelApi,
      maxOutputTokens: options.maxOutputTokens,
      structuralRulesVersion: SPECTRE_STRUCTURAL_RULES_VERSION,
      scannerConfig,
    };
  }

  private now(): number {
    return this.options.now?.() ?? Date.now();
  }

  private descriptor(request: SpectreCacheRequest): string {
    return sha256(canonicalJson({
      ...this.baseDescriptor,
      request: {
        key: request.key,
        systemPrompt: request.systemPrompt,
        userPrompt: request.userPrompt,
        responseSchema: request.responseSchema,
        sources: request.sources,
      },
    }));
  }

  private key(descriptor: string): string {
    return `${this.prefix}:${descriptor}`;
  }

  private sign(payload: CacheEnvelopePayload): string {
    return createHmac('sha256', this.options.hmacKey).update(canonicalJson(payload)).digest('hex');
  }

  private decode(raw: string, descriptor: string): CacheEnvelopePayload | null {
    if (Buffer.byteLength(raw, 'utf8') > MAX_ENVELOPE_BYTES) return null;
    try {
      const envelope = JSON.parse(raw) as Partial<CacheEnvelope>;
      const payload = envelope.payload;
      if (!payload || typeof envelope.signature !== 'string') return null;
      if (payload.version !== CACHE_VERSION || payload.scope !== this.scope || payload.descriptor !== descriptor) return null;
      if (payload.resultClass !== 'positive' && payload.resultClass !== 'negative') return null;
      if (!Number.isSafeInteger(payload.agreements) || payload.agreements < 1 || payload.agreements > 1_000) return null;
      if (!Number.isSafeInteger(payload.createdAt) || !Number.isSafeInteger(payload.expiresAt) || payload.expiresAt <= this.now()) return null;
      if (typeof payload.text !== 'string' || Buffer.byteLength(payload.text, 'utf8') > MAX_RESPONSE_BYTES) return null;
      return timingSafeHexEqual(envelope.signature, this.sign(payload as CacheEnvelopePayload))
        ? payload as CacheEnvelopePayload
        : null;
    } catch {
      return null;
    }
  }

  private available(): boolean {
    return this.now() >= this.disabledUntil;
  }

  private succeeded(): void {
    this.failures = 0;
  }

  private failed(operation: string): void {
    this.failures++;
    if (this.failures >= CIRCUIT_FAILURES) this.disabledUntil = this.now() + CIRCUIT_COOLDOWN_MS;
    spectreCacheOperationsTotal.inc({ operation, outcome: 'error', result: 'none' });
  }

  private async readPayload(request: SpectreCacheRequest, metric = true): Promise<{
    payload: CacheEnvelopePayload;
    descriptor: string;
    raw: string;
  } | null> {
    if (!this.available()) {
      if (metric) spectreCacheOperationsTotal.inc({ operation: 'read', outcome: 'bypassed', result: 'none' });
      return null;
    }
    const descriptor = this.descriptor(request);
    try {
      const raw = await this.options.client.get(this.key(descriptor));
      this.succeeded();
      if (raw === null) {
        if (metric) spectreCacheOperationsTotal.inc({ operation: 'read', outcome: 'miss', result: 'none' });
        return null;
      }
      const payload = this.decode(raw, descriptor);
      if (!payload) {
        if (metric) spectreCacheOperationsTotal.inc({ operation: 'read', outcome: 'invalid', result: 'none' });
        await this.invalidate(request, raw);
        return null;
      }
      if (metric) spectreCacheOperationsTotal.inc({ operation: 'read', outcome: 'hit', result: payload.resultClass });
      return { payload, descriptor, raw };
    } catch {
      this.failed('read');
      return null;
    }
  }

  private async observeForWrite(request: SpectreCacheRequest): Promise<{
    descriptor: string;
    raw: string | null;
    payload: CacheEnvelopePayload | null;
  } | null> {
    if (!this.available()) return null;
    const descriptor = this.descriptor(request);
    try {
      const raw = await this.options.client.get(this.key(descriptor));
      this.succeeded();
      return { descriptor, raw, payload: raw === null ? null : this.decode(raw, descriptor) };
    } catch {
      this.failed('read');
      return null;
    }
  }

  async read(request: SpectreCacheRequest): Promise<SpectreCachedResponse | null> {
    if (this.mode === 'off' || this.mode === 'write-only') return null;
    const stored = await this.readPayload(request);
    return stored ? {
      text: stored.payload.text,
      resultClass: stored.payload.resultClass,
      agreements: stored.payload.agreements,
      validationToken: stored.raw,
    } : null;
  }

  async write(request: SpectreCacheRequest, text: string, resultClass: SpectreCacheResultClass): Promise<void> {
    if (this.mode === 'off' || !this.available() || Buffer.byteLength(text, 'utf8') > MAX_RESPONSE_BYTES) return;
    for (let attempt = 0; attempt < 3; attempt++) {
      const observed = await this.observeForWrite(request);
      if (!observed) return;
      if (observed.payload?.resultClass === 'positive' && resultClass === 'negative') {
        spectreCacheOperationsTotal.inc({ operation: 'write', outcome: 'preserved', result: 'positive' });
        return;
      }
      if (observed.payload?.resultClass === 'positive' && resultClass === 'positive'
        && !isFindingSuperset(text, observed.payload.text)) {
        spectreCacheOperationsTotal.inc({ operation: 'write', outcome: 'preserved', result: 'positive' });
        return;
      }
      const agreements = resultClass === 'negative' && observed.payload?.resultClass === 'negative'
        ? Math.min(observed.payload.agreements + 1, 1_000)
        : 1;
      const ttl = resultClass === 'positive'
        ? this.options.config.cache!.positiveTtlSeconds
        : this.options.config.cache!.negativeTtlSeconds;
      const now = this.now();
      const payload: CacheEnvelopePayload = {
        version: CACHE_VERSION,
        scope: this.scope,
        descriptor: observed.descriptor,
        resultClass,
        agreements,
        createdAt: now,
        expiresAt: now + ttl * 1000,
        text,
      };
      const serialized = canonicalJson({ payload, signature: this.sign(payload) });
      const serializedBytes = Buffer.byteLength(serialized, 'utf8');
      if (serializedBytes > MAX_ENVELOPE_BYTES) return;
      try {
        const evaluated = await this.options.client.eval(
          WRITE_SCRIPT,
          5,
          this.key(observed.descriptor),
          ...this.metadataKeys,
          observed.raw ?? '__LAYNE_MISSING__',
          serialized,
          ttl,
          now,
          serializedBytes,
          this.options.maxBytes,
        );
        const outcome = Array.isArray(evaluated) ? Number(evaluated[0]) : Number(evaluated);
        this.succeeded();
        if (outcome === -1) continue;
        if (outcome === 0) {
          spectreCacheOperationsTotal.inc({ operation: 'write', outcome: 'budget-rejected', result: resultClass });
          return;
        }
        spectreCacheOperationsTotal.inc({ operation: 'write', outcome: 'success', result: resultClass });
        (spectreCacheEntryBytes as { observe(value: number): void }).observe(serializedBytes);
        return;
      } catch {
        this.failed('write');
        return;
      }
    }
    spectreCacheOperationsTotal.inc({ operation: 'write', outcome: 'conflict', result: resultClass });
  }

  async invalidate(request: SpectreCacheRequest, validationToken?: string): Promise<void> {
    if (!this.available() || validationToken === undefined) return;
    const descriptor = this.descriptor(request);
    try {
      const evaluated = await this.options.client.eval(
        DELETE_SCRIPT,
        5,
        this.key(descriptor),
        ...this.metadataKeys,
        validationToken,
      );
      this.succeeded();
      spectreCacheOperationsTotal.inc({
        operation: 'delete',
        outcome: Number(evaluated) === -1 ? 'conflict' : 'success',
        result: 'none',
      });
    } catch {
      this.failed('delete');
    }
  }

  recordVerification(cached: SpectreCacheResultClass, live: SpectreCacheResultClass, matches: boolean): void {
    spectreCacheOperationsTotal.inc({
      operation: 'verify',
      outcome: matches ? 'match' : 'disagreement',
      result: `${cached}-${live}`,
    });
  }

  recordServed(resultClass: SpectreCacheResultClass): void {
    spectreCacheOperationsTotal.inc({ operation: 'serve', outcome: 'success', result: resultClass });
  }
}

let productionClient: Redis | null = null;

function getProductionClient(): Redis {
  if (productionClient) return productionClient;
  productionClient = new Redis(process.env.SPECTRE_CACHE_REDIS_URL ?? process.env.REDIS_URL ?? 'redis://localhost:6379', {
    maxRetriesPerRequest: 1,
    connectTimeout: 2_000,
    commandTimeout: 1_000,
    lazyConnect: true,
    enableOfflineQueue: false,
    autoResendUnfulfilledCommands: false,
  });
  void productionClient.connect().catch(() => {});
  productionClient.on('error', () => {
    // Operations are fail-open and instrument their own errors.
  });
  return productionClient;
}

export function createProductionSpectreCache({
  context,
  provider,
  model,
  modelApi,
  maxOutputTokens,
  config,
}: {
  context?: SpectreCacheContext;
  provider: string;
  model: string;
  modelApi: string;
  maxOutputTokens: number;
  config: SpectreConfig;
}): SpectreResponseCache | undefined {
  const mode = spectreCacheModeFromEnv();
  if (!config.cache?.enabled || mode === 'off' || !context || !validContext(context)) return undefined;
  const hmacKey = process.env.SPECTRE_CACHE_HMAC_KEY;
  const maxBytes = Number(process.env.SPECTRE_CACHE_MAX_BYTES);
  if (!hmacKey || Buffer.byteLength(hmacKey, 'utf8') < 32 || !Number.isSafeInteger(maxBytes) || maxBytes < 1024 * 1024) return undefined;
  const buildVersion = process.env.LAYNE_BUILD_SHA;
  if (!buildVersion) return undefined;
  return new RedisSpectreResponseCache({
    client: getProductionClient(),
    context,
    provider,
    model,
    modelApi,
    maxOutputTokens,
    config,
    mode,
    hmacKey,
    maxBytes,
    buildVersion,
    epoch: process.env.SPECTRE_CACHE_EPOCH ?? '1',
  });
}

export async function closeSpectreCacheClient(): Promise<void> {
  const client = productionClient;
  productionClient = null;
  if (!client) return;
  try {
    await client.quit();
  } catch {
    client.disconnect();
  }
}

import { beforeEach, describe, expect, it, vi } from 'vitest';

const metricMocks = vi.hoisted(() => ({
  backendErrors: vi.fn(),
  circuitState: vi.fn(),
  leaseRecoveries: vi.fn(),
}));

vi.mock('../metrics.js', () => ({
  spectreCircuitState: { set: metricMocks.circuitState },
  spectreGovernorBackendErrorsTotal: { inc: metricMocks.backendErrors },
  spectreGovernorLeaseRecoveriesTotal: { inc: metricMocks.leaseRecoveries },
